package sv.edu.udb.pokebattle.client;
import com.fasterxml.jackson.annotation.*; import lombok.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*;
@Component @RequiredArgsConstructor public class PokeApiClient { private final RestClient pokeApiRestClient;
 public ListaResponse listar(int offset,int limit){return pokeApiRestClient.get().uri("/pokemon?offset={offset}&limit={limit}",offset,limit).retrieve().body(ListaResponse.class);} public PokemonResponse pokemon(String v){return pokeApiRestClient.get().uri("/pokemon/{valor}",v.toLowerCase()).retrieve().body(PokemonResponse.class);} public MovimientoResponse movimiento(int id){return pokeApiRestClient.get().uri("/move/{id}",id).retrieve().body(MovimientoResponse.class);}
 @JsonIgnoreProperties(ignoreUnknown=true) public record RecursoNombrado(String name,String url){} @JsonIgnoreProperties(ignoreUnknown=true) public record ListaResponse(int count,String next,String previous,List<RecursoNombrado> results){} @JsonIgnoreProperties(ignoreUnknown=true) public record Estadistica(@JsonProperty("base_stat") int baseStat,RecursoNombrado stat){} @JsonIgnoreProperties(ignoreUnknown=true) public record Tipo(RecursoNombrado type){} @JsonIgnoreProperties(ignoreUnknown=true) public record Sprite(@JsonProperty("front_default") String frontDefault){} @JsonIgnoreProperties(ignoreUnknown=true) public record MovimientoPokemon(RecursoNombrado move){} @JsonIgnoreProperties(ignoreUnknown=true) public record PokemonResponse(int id,String name,Sprite sprites,List<Estadistica> stats,List<Tipo> types,List<MovimientoPokemon> moves){} @JsonIgnoreProperties(ignoreUnknown=true) public record MovimientoResponse(int id,String name,Integer power,Integer accuracy,RecursoNombrado type){} }
